'use strict';
const $ = id => document.getElementById(id);
const fixtures = {
 dry: {baseline:7.0, title:'Give your crop a head start.', summary:'Explore earlier sowing to move the sensitive growth stage away from late-season drought.', priority:'Timing', note:'Before the dry spell', message:'Earlier growth can reduce overlap with the dry spell.', plans:[{name:'Earlier sowing',method:'Tree of Thoughts',yield:8.8,stress:'Lower',desc:'Move growth ahead of the dry spell.',steps:['Discuss an earlier sowing window with your local agronomist; confirm adequate establishment moisture.','Review water availability before the crop’s sensitive reproductive stage.','Recheck the local forecast and field moisture before any operation.']},{name:'Moisture first',method:'Plan-and-Solve',yield:8.1,stress:'Moderate',desc:'Retain moisture through the season.',steps:['Discuss residue retention or mulching options suited to this field.','Prioritize available water around sensitive growth stages.','Review nutrient timing with an agronomist using the soil test.']},{name:'Build soil resilience',method:'Reflexion',yield:7.9,stress:'Moderate',desc:'Use lessons from previous seasons.',steps:['Review how this field performed during previous dry seasons.','Assess organic matter and soil preparation with a local expert.','Document field moisture and growth observations for next season.']}]},
 normal:{baseline:8.1,title:'Make the most of a steady season.',summary:'Explore a balanced plan that coordinates crop establishment, available moisture and nutrient timing.',priority:'Balance',note:'Match inputs to growth',message:'Well-timed inputs support a steadier growth period.',plans:[{name:'Balanced timing',method:'Tree of Thoughts',yield:9.2,stress:'Lower',desc:'Coordinate sowing and crop demand.',steps:['Confirm the local sowing window and establishment moisture.','Use a soil test to review staged nutrient applications with an agronomist.','Monitor rainfall before committing supplementary irrigation.']},{name:'Staged inputs',method:'Plan-and-Solve',yield:8.9,stress:'Lower',desc:'Revisit inputs as the crop grows.',steps:['Review nutrient needs at each growth stage.','Adjust the draft after observing actual rainfall.','Check crop development with the field advisor.']},{name:'Season memory',method:'Reflexion',yield:8.7,stress:'Moderate',desc:'Adapt a familiar seasonal approach.',steps:['Compare the field with records from similar seasons.','Review which timing choices previously worked well.','Record observations to improve next season’s plan.']}]},
 wet:{baseline:7.2,title:'Plan around the rain, not the calendar.',summary:'Explore drainage-aware timing and staged inputs to reduce exposure to excess water and nutrient loss.',priority:'Drainage',note:'Watch wet field conditions',message:'The selected plan reduces modeled exposure to excess water in this demo.',plans:[{name:'Rain-aware timing',method:'Tree of Thoughts',yield:8.6,stress:'Lower',desc:'Work around intense rainfall.',steps:['Inspect drainage and discuss waterlogging risks with an agronomist.','Review sowing and field operations against the local forecast.','Review nutrient timing after heavy rain using field observations.']},{name:'Split applications',method:'Plan-and-Solve',yield:8.2,stress:'Moderate',desc:'Reduce exposure of inputs to rain.',steps:['Review staged nutrient applications with your agronomist.','Avoid treating this draft as a fixed application calendar.','Reassess the crop after significant rainfall.']},{name:'Wet-season lessons',method:'Reflexion',yield:8.0,stress:'Moderate',desc:'Learn from earlier wet seasons.',steps:['Review previous waterlogging locations in the field.','Discuss field access and drainage before operations.','Record rain impacts to inform the next advisory.']}]}
};
let state={scenario:'dry',selected:0,field:'Lakshmi’s north field',area:2,soil:'sandy',water:'limited'};
let records=[];try{records=JSON.parse(localStorage.getItem('fieldwise-drafts-v1')||'[]');if(!Array.isArray(records))records=[];records=records.filter(r=>r&&typeof r.text==='string'&&typeof r.field==='string'&&typeof r.plan==='string');}catch{records=[];}
let draft=null, busy=false, toastTimer;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function current(){const f=fixtures[state.scenario],p=f.plans[state.selected];const delta=(state.soil==='loam'?.2:state.soil==='clay'?(state.scenario==='wet'?-.3:.1):0)+(state.water==='reliable'?.3:state.water==='rainfed'?-.5:0);return{f,p,y:Math.max(0,p.yield+delta),baseline:Math.max(.1,f.baseline+delta)};}
function selectPlan(index){if(!Number.isInteger(index)||index<0||index>2)throw new Error('Choose plan 0, 1 or 2.');state.selected=index;render();}
function render(){const {f,p,y,baseline}=current();$('plan-title').textContent=state.selected===0?f.title:p.name+' for this season.';$('plan-summary').textContent=state.selected===0?f.summary:p.desc+' Review this approach alongside the other plans before preparing a draft.';$('strategy-tag').textContent=p.method;$('yield').innerHTML=y.toFixed(1)+' <small>t/ha</small>';$('gain').textContent='+'+Math.round((y/baseline-1)*100)+'% vs. demo baseline';$('stress').textContent=p.stress;$('priority').textContent=f.priority;$('priority-note').textContent=f.note;$('chart-message').textContent=f.message;$('result-status').textContent='3 illustrative plans';$('plan-cards').innerHTML=f.plans.map((plan,i)=>`<button class="plan-card ${state.selected===i?'selected':''}" aria-pressed="${state.selected===i}" data-plan="${i}"><span class="plan-number">PATH 0${i+1}</span><span class="radio" aria-hidden="true"></span><b>${plan.name}</b><p>${plan.desc}</p><span class="yield-small">${(plan.yield+y-p.yield).toFixed(1)} <small>t/ha · demo</small></span></button>`).join('');$('plan-cards').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>selectPlan(Number(b.dataset.plan))));renderChart();$('saved-count').textContent=records.length;}
function renderChart(){const base=state.scenario==='dry'?[.15,.24,.38,.75,.9,.58]:state.scenario==='wet'?[.35,.65,.86,.7,.47,.3]:[.15,.27,.39,.49,.38,.23];const factor=.48+state.selected*.15+(state.water==='rainfed'?.1:state.water==='reliable'?-.08:0);const chosen=base.map((n,i)=>Math.max(.05,n*factor+(i===1?.08:0)));const pts=a=>a.map((n,i)=>`${48+i*100},${139-n*100}`).join(' ');const labs=['Sowing','Seedling','Vegetative','Flowering','Grain fill','Maturity'];$('chart').innerHTML=`<svg viewBox="0 0 600 177" role="img" aria-label="Illustrative water stress chart. Baseline stress is higher than the selected plan; this is authored demo data."><title>Illustrative water stress, not a crop simulation</title>${[0,.5,1].map(n=>`<line x1="48" x2="548" y1="${139-n*100}" y2="${139-n*100}" stroke="#e9eee6" stroke-dasharray="3 4"/><text x="17" y="${143-n*100}" fill="#8b9687" font-size="10">${n.toFixed(1)}</text>`).join('')}<polygon points="48,139 ${pts(chosen)} 548,139" fill="#eff4e8"/><polyline points="${pts(base)}" fill="none" stroke="#b3beab" stroke-width="2" stroke-dasharray="5 5"/><polyline points="${pts(chosen)}" fill="none" stroke="#6b884b" stroke-width="2.5"/>${chosen.map((n,i)=>`<circle cx="${48+i*100}" cy="${139-n*100}" r="3.5" fill="#6b884b" stroke="white" stroke-width="2"/>`).join('')}${labs.map((t,i)=>`<text x="${48+i*100}" y="163" text-anchor="middle" fill="#899382" font-size="9">${t}</text>`).join('')}</svg>`;}
async function runScenario(){if(busy)return;if(!$('field-form').reportValidity())return;busy=true;$('run').disabled=true;$('run').textContent='Preparing comparison…';$('loading').hidden=false;$('results').hidden=true;state={scenario:document.querySelector('input[name=scenario]:checked').value,selected:0,field:$('field-name').value.trim()||'Untitled field',area:Number($('area').value),soil:$('soil').value,water:$('water').value};await new Promise(r=>setTimeout(r,650));render();$('loading').hidden=true;$('results').hidden=false;$('run').disabled=false;$('run').textContent='✧  Explore crop plans';busy=false;toast('Comparison updated for '+state.field);return{scenario:state.scenario,plans:fixtures[state.scenario].plans.map(p=>p.name),illustrative:true};}
$('field-form').addEventListener('submit',e=>{e.preventDefault();runScenario();});$('field-form').addEventListener('input',()=>{$('result-status').textContent='Inputs changed · explore to update';});
function openAdvisory(){const {p,y}=current();const scenario={dry:'Dry season',normal:'Typical monsoon',wet:'Heavy rainfall'}[state.scenario];const soil={sandy:'Red sandy soil',loam:'Loamy soil',clay:'Clay soil'}[state.soil];const water={limited:'Limited irrigation',rainfed:'Rainfed only',reliable:'Reliable irrigation'}[state.water];const meta=`${state.area} ha · Maize · Mandya, Karnataka`;draft={id:Date.now().toString(),field:state.field,plan:p.name,date:new Date().toLocaleDateString('en-IN'),text:`FIELDWISE — DEMO ADVISORY DRAFT\nAgronomist review required. Not field instructions.\n\n${state.field}\n${meta}\n${soil} · ${water}\nScenario: ${scenario}\nPlan: ${p.name}\n\nDiscussion points\n${p.steps.map((s,i)=>`${i+1}. ${s}`).join('\n')}\n\nIllustrative yield: ${y.toFixed(1)} t/ha (${(y*state.area).toFixed(1)} tonnes across this field). These are authored demo values, not forecasts or APSIM outputs.\n\nBefore acting: confirm field conditions, local weather, soil test and agronomist approval.\n\nResearch inspiration: https://arxiv.org/pdf/2607.00454\n`};$('advisory-content').innerHTML=`<h3>${escapeHTML(state.field)}</h3><p>${escapeHTML(meta)}<br>${soil} · ${water}<br>${scenario} · ${p.name}</p><h3>Discuss with the farmer</h3><ol>${p.steps.map(s=>`<li>${s}</li>`).join('')}</ol><p class="muted">Illustrative yield: ${y.toFixed(1)} t/ha · ${(y*state.area).toFixed(1)} tonnes across this field. Demo values, not predictions.</p><p><b>Before acting:</b> confirm field conditions, local weather, soil test and agronomist approval.</p>`;$('save').disabled=false;$('save').textContent='Save on this device';$('advisory-dialog').showModal();}
$('advisory').addEventListener('click',openAdvisory);$('close-dialog').addEventListener('click',()=>$('advisory-dialog').close());$('advisory-dialog').addEventListener('click',e=>{if(e.target===$('advisory-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function downloadText(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('download').addEventListener('click',()=>{if(draft)downloadText(draft.text,'fieldwise-advisory.txt');});$('save').addEventListener('click',()=>{if(!draft)return;const next=[draft,...records];try{localStorage.setItem('fieldwise-drafts-v1',JSON.stringify(next));records=next;$('saved-count').textContent=records.length;$('save').disabled=true;$('save').textContent='Saved';toast('Advisory saved on this device');renderSaved();}catch{toast('Device storage unavailable. Download the advisory instead.');}});
function renderSaved(){$('saved-list').innerHTML=records.length?records.map((r,i)=>`<article class="panel saved-card"><div><h3>${escapeHTML(r.field)}</h3><p>${escapeHTML(r.plan)} · ${escapeHTML(r.date||'')} · Demo draft</p></div><button class="secondary" data-download="${i}">Download advisory</button></article>`).join(''):'<div class="panel empty"><h2>Your first advisory starts with a plan.</h2><p>Explore a scenario, prepare an advisory, and save it here.</p><button class="primary" id="start-planning">Open season planner</button></div>';$('saved-list').querySelectorAll('[data-download]').forEach(b=>b.addEventListener('click',()=>downloadText(records[Number(b.dataset.download)].text,'fieldwise-advisory.txt')));$('start-planning')?.addEventListener('click',()=>showView('planner'));}
function showView(view){if(!['planner','saved','research'].includes(view))return;for(const v of ['planner','saved','research'])$(v+'-view').hidden=v!==view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('breadcrumb').textContent={planner:'Season planner',saved:'Saved advisories',research:'Research & method'}[view];if(view==='saved')renderSaved();window.scrollTo({top:0,behavior:'instant'});}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'select_crop_plan',title:'Select a crop plan',description:'Select one of the three illustrative crop plans in the current comparison. Does not save an advisory.',inputSchema:{type:'object',properties:{plan_index:{type:'integer',minimum:0,maximum:2}},required:['plan_index'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='plan_index'))throw new Error('Expected only plan_index.');selectPlan(input.plan_index);return{selected_plan:current().p.name,illustrative:true};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
